def integrate_DOS(energy, energy_vertices):
    '''Input:
    energy: a float number representing the energy value at which the density of states will be integrated
    energy_vertices: a list of float numbers representing the energy values at the four vertices of a tetrahedron when implementing the linear tetrahedron method
    Output:
    result: a float number representing the integration results of the density of states
    '''
    # Initialize the e_ji symbols and their numerical values (from previous step)
    symbols, value_map = init_eji_array(energy, energy_vertices)

    # Convenience accessor for the numeric value of e_{ji}
    def v(j, i):
        return float(value_map[symbols['e_{}{}'.format(j, i)]])

    eps = sorted([float(e) for e in energy_vertices])
    e1, e2, e3, e4 = eps
    E = float(energy)

    # Normalized DOS contribution (the factor 6*Omega_T/Omega_BZ is omitted,
    # i.e. the result is given in units of the tetrahedron volume fraction)
    if E < e1 or E > e4:
        result = 0.0
    elif e1 <= E < e2:
        # 3 * (E - e1)^2 / (e21 * e31 * e41)
        denom = v(2, 1) * v(3, 1) * v(4, 1)
        if denom == 0.0:
            result = 0.0
        else:
            result = 3.0 * v(0, 1) ** 2 / denom
    elif e2 <= E < e3:
        denom = v(3, 1) * v(4, 1)
        if denom == 0.0:
            result = 0.0
        else:
            num = v(2, 1) + 2.0 * v(0, 2) - (v(3, 2) + v(4, 2)) * v(0, 2) ** 2 / (v(3, 2) * v(4, 2))
            result = 1.0 / denom * num
    elif e3 <= E <= e4:
        denom = v(4, 1) * v(4, 2) * v(4, 3)
        if denom == 0.0:
            result = 0.0
        else:
            result = 3.0 * v(4, 0) ** 2 / denom
    else:
        result = 0.0

    return result
